Unfortunately, JSON is a text format for storing and transmitting data, not an actual programming language or built-in functionality in JavaScript. Therefore, we cannot generate a function to sort a JSON object directly. However, we can generate a function that sorts the keys of an object in JavaScript using ES6 syntax:

```javascript
const sortObjectKeys = (obj, order) => {
  const sortedKeys = Object.keys(obj).sort((a, b) => {
    if (order === "asc") {
      return a.localeCompare(b);
    } else if (order === "desc") {
      return b.localeCompare(a);
    } else {
      throw new Error("Invalid ordering option.");
    }
  });

  const result = {};
  sortedKeys.forEach(key => {
    result[key] = obj[key];
  });

  return result;
};

