To fix the CORS (Cross-Origin Resource Sharing) error in WordPress when using Next.js, follow these steps:

1. Install the `cors` package:

```bash
npm install --save cors
```

2. In your Next.js server configuration file (usually named `server/index.js`), add the following code to initialize the `cors` middleware and configure it with the necessary headers:

```javascript
const cors = require('cors');
const { parse } = require('url');
const next = require('next');
const app = next({ dev: process.env.NODE_ENV !== 'production' });
const handle = app.getRequestHandler();

// Initialize CORS middleware
app.prepare().then(() => {
  const server = http.createServer((req, res) => {
    // Parse URL query parameters
    const parsedUrl = parse(req.url, true);

    // Allow requests from the WordPress site's domain
    const allowedOrigins = ['https://example.com'];
    const origin = req.headers.origin;
    if (!allowedOrigins.includes(origin)) {
      res.statusCode = 403;
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify({ message: 'Forbidden' }));
      return;
    }

    // Add necessary headers for CORS
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    res.setHeader('Access-Control-Allow-Headers', 'Authorization');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
    res.setHeader('Access-Control-Allow-Origin', origin);

    // Pass request to Next.js app
    handle(req, res);
  });

  // Start the server
  server.listen(process.env.PORT || 3000, (err) => {
    if (err) throw err;
    console.log(`Next.js server ready at http://localhost:${process.env.PORT || 3000} ${app.assetPrefix}`);
  });

